fn execute(service : MockService, key : ActionKey, amount : Int, attempt : Int, failures : Int) : Response =
  if recorded(service, key) then
    Response { service = audit(service, ExecuteKind, key, attempt, Replayed), outcome = Replayed }
  elif transients(service, key) < failures then
    Response { service = audit(service, ExecuteKind, key, attempt, Transient), outcome = Transient }
  else
    let applied = MockService { ..service, effects = append(service.effects, [Effect { key = key, amount = amount }]) }
    Response { service = audit(applied, ExecuteKind, key, attempt, Applied), outcome = Applied }

